#if UNITY_EDITOR
using System.Linq;
using System.Reflection;
using Game.Vehicle.Runtime;
using NUnit.Framework;
using UnityEditor;
using UnityEngine;

namespace Game.Tests
{
    /// <summary>
    /// Track A7: the TRAKT prefab (generated by Kamion/Setup/Rebuild TRAKT truck, outside git) is driven by the solver
    /// state: wheels spin with the wheel speed, the front wheels steer with the road-wheel angle, the cab follows the cab
    /// suspension (pitch, roll, heave), the steering wheel turns with the handwheel angle. The solver state is set directly
    /// (no global Physics.Simulate, which would also step bodies left in other scenes by earlier tests). Inconclusive when
    /// the prefab has not been generated in this checkout.
    /// </summary>
    public class TraktTruckRigTests
    {
        const string PrefabPath = "Assets/_Generated/Truck/Tractor4x2_TRAKT.prefab";
        GameObject m_Truck;

        [TearDown]
        public void TearDown()
        {
            if (m_Truck != null) Object.DestroyImmediate(m_Truck);
        }

        [Test]
        public void Rig_FollowsSolverState_WheelsSpinAndSteer_CabAndSteeringWheel()
        {
            var prefab = AssetDatabase.LoadAssetAtPath<GameObject>(PrefabPath);
            Assume.That(prefab, Is.Not.Null, "TRAKT prefab not generated (Kamion/Setup/Rebuild TRAKT truck)");
            m_Truck = Object.Instantiate(prefab, new Vector3(0f, -900f, 0f), Quaternion.identity);
            var body = m_Truck.GetComponent<VehicleBody>();
            if (!body.Initialized) body.Initialize(body.Data);
            var rbody = m_Truck.GetComponent<Rigidbody>();
            rbody.isKinematic = true;
            var vis = body.GetComponent<VehicleVisuals>();

            Assert.That(vis.wheelPivots.Length, Is.EqualTo(body.Model.Wheels.Length));
            foreach (var s in vis.wheelSpinners)
                Assert.That(s.GetComponentsInChildren<Renderer>(true).Length, Is.GreaterThan(0), "art wheel under the physics spinner " + s.parent.name);
            Assert.IsNotNull(vis.cabPivot.Find("DriverEyePoint"), "eye point on the cab-suspension pivot");
            Assert.IsNull(m_Truck.GetComponentsInChildren<Transform>(true).FirstOrDefault(t => t.name.StartsWith("CAB_ShellPlaceholder")), "interior shell placeholder removed");
            Assert.That(m_Truck.GetComponentsInChildren<RenderTextureMirror>(true).Length, Is.EqualTo(2), "two render-texture main mirrors");

            var late = typeof(VehicleVisuals).GetMethod("LateUpdate", BindingFlags.Instance | BindingFlags.NonPublic);
            late.Invoke(vis, null);
            var steerRest = vis.steeringWheel.localRotation;
            var cabRest = vis.cabPivot.localPosition;
            var spinRest = vis.wheelSpinners.Select(s => s.localRotation).ToArray();

            var m = body.Model;
            foreach (var w in m.Wheels) { w.Omega = 8.0; if (w.HardpointLocal.ToUnity().z > 1.85f) w.SteerAngle = 0.25; }
            m.Steering.Angle = 0.25;
            m.Cab.Pitch = 0.02; m.Cab.Roll = -0.01; m.Cab.Heave = 0.01;
            for (int i = 0; i < 5; i++) vis.Capture(0.01f);
            late.Invoke(vis, null);

            for (int i = 0; i < vis.wheelSpinners.Length; i++)
                Assert.That(Quaternion.Angle(spinRest[i], vis.wheelSpinners[i].localRotation), Is.GreaterThan(5f), "wheel spin from the solver: " + vis.wheelPivots[i].name);
            int steered = vis.wheelPivots.Count(p => Mathf.Abs(Mathf.DeltaAngle(0f, p.localEulerAngles.y) - 0.25f * Mathf.Rad2Deg) < 0.5f);
            Assert.That(steered, Is.EqualTo(2), "front wheels at the road-wheel angle");
            Assert.That(Quaternion.Angle(steerRest, vis.steeringWheel.localRotation), Is.GreaterThan(10f), "steering wheel turns with the handwheel");
            Assert.AreEqual(cabRest.y - 0.01f, vis.cabPivot.localPosition.y, 1e-4f, "cab heave");
            Assert.That(Quaternion.Angle(Quaternion.identity, vis.cabPivot.localRotation), Is.GreaterThan(0.5f), "cab pitch/roll");
        }
    }
}
#endif
